import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`use-every-dollar`,heroTitle:`Put every dollar to work in minutes`,heroSubtitle:`Perplexity Computer analyzes your salary, builds a zero-based budget, and maps every dollar to a goal — automatically.`,heroCta:`Optimize My Income`,inputUrlCta:`Optimize My Income`,inputUrlPlaceholder:`Your approximate take-home pay`,inputUrlPrefill:`Connect my accounts and build a plan for every dollar of my income. I make approximately {url} — but ask me more about my financial goals and obligations to get the full picture. Then build a complete paycheck allocation plan. 1) Map my take-home pay against every fixed and variable expense. 2) Find every unassigned dollar — show me where untracked spending is going. 3) Build 3 allocation scenarios (conservative, balanced, aggressive) and show me the 5-year compounding difference of each. 4) Assign every dollar to a job — savings, investing, debt payoff, living expenses, and discretionary. 5) Set up weekly check-ins to keep me on track. Ask me which goals matter most so you can prioritize the allocation.`,heroOverlaySteps:[`Analyzing your income, expenses, and financial obligations`,`Building a zero-based budget that accounts for every dollar`,`Mapping allocations to savings, investing, and debt payoff goals`,`Monthly cash flow calendar, fund recommendations, and quick wins — ready to execute`],generatingSteps:[`Visiting {url} to understand your income, expenses, and financial picture`,`Designing an agent to build a zero-based budget tailored to your salary`,`Configuring savings, investing, and debt payoff strategies for your situation`,`Setting up a monthly cash flow calendar and actionable quick wins`],featureSectionTitle:`From paycheck to plan`,featureCardTitles:[`Connects to your financial stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Mint, YNAB — Computer plugs into your tools so budgets, trackers, and savings goals stay synced in one workflow.`,`Zero-based budget breakdown. Debt payoff comparison. Investment allocation plan. Monthly cash flow calendar. Computer delivers a plan you can follow starting today.`],capabilitySectionTitle:`Your financial planner, on autopilot`,capabilitySectionSubtitle:`Enter your salary, step away, come back to a complete money plan.`,capabilityCards:[{title:`Income Analysis`,description:`Computer can break down your take-home pay, tax withholdings, and recurring deductions — so you know exactly what you’re working with.`},{title:`Budget Allocation`,description:`Computer can build a zero-based budget that assigns every dollar to essentials, savings, debt, and discretionary spending — tailored to your goals.`},{title:`Investment Mapping`,description:`Computer can research high-yield savings accounts, index funds, and retirement contributions — and recommend where each investing dollar should go.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, YNAB, and more — build workflows that keep your budget and trackers up to date.`},{title:`Remember & Learn`,description:`Computer can remember your income, goals, and spending patterns across sessions — so every plan builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can track your spending against your budget and flag when you’re off pace — set up alerts so no dollar slips through the cracks.`}]});export{t as default};
